/**
 * Lazy URLs for the Avatar FX template thumbnails (Annie renders generated by
 * `pnpm -s effects:thumbnails`). Each image is a separate build asset that is
 * fetched only when its card is shown.
 */
const THUMBNAIL_LOADERS = import.meta.glob<string>(
  "../../assets/effect-templates/*.webp",
  { query: "?url", import: "default" },
);

const LOADERS_BY_ID = new Map(
  Object.entries(THUMBNAIL_LOADERS).map(([path, load]) => [
    path.replace(/^.*\/([^/]+)\.webp$/, "$1"),
    load,
  ]),
);

/** Template IDs that have a bundled thumbnail. */
export function avatarEffectTemplateThumbnailIds(): string[] {
  return [...LOADERS_BY_ID.keys()].sort();
}

/** Resolve one template's thumbnail URL, or null when none is bundled. */
export function loadAvatarEffectTemplateThumbnail(
  id: string,
): Promise<string> | null {
  return LOADERS_BY_ID.get(id)?.() ?? null;
}
